import React from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import HomePage from "./pages/HomePage";
import LoginPage from "./pages/LoginPage.jsx";

function App() {
  <Route path="/LoginPage" element={<LoginPage />} />
  return <HomePage />;
}

export default App;
